"""Article-specific editorial source for CC-09 (Civil Code arts. 551-610)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {"target": target, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}]}


ROWS = {
    "551": row("Na doação conjunta a várias pessoas, a divisão é igual, salvo declaração diferente. Entre cônjuges donatários, a parte do falecido acresce ao sobrevivente.", "A regra supre o silêncio do doador sobre quotas e cria, para o casal beneficiado em conjunto, direito especial de acrescer sobre toda a liberalidade.", "Doador entrega imóvel ao casal sem fixar percentuais; morrendo um deles, o outro conserva a totalidade.", "A solução pode ser afastada por declaração expressa. Para donatários que não sejam cônjuges, a morte não produz esse acréscimo automático.", "Direito de acrescer", "concentração, no beneficiário sobrevivente, da parte que caberia ao outro"),
    "552": row("Em regra, o doador não paga juros de mora nem responde por evicção ou defeito oculto. Na doação destinada a casamento determinado, responde por evicção, salvo pacto contrário.", "Por ser liberalidade, a doação recebe responsabilidade menos extensa que contratos onerosos. A exceção protege a finalidade matrimonial especificamente indicada.", "Pessoa doa bem para o casamento da filha e depois o casal perde esse bem por direito anterior de terceiro.", "A exceção legal refere-se à evicção, não transforma toda doação em contrato oneroso nem elimina cláusula válida em sentido contrário.", "Evicção", "perda do bem por decisão que reconhece direito anterior de terceiro"),
    "553": row("Quem recebe doação com encargo deve cumpri-lo, seja ele favorável ao doador, a terceiro ou ao interesse coletivo. Se for coletivo, o Ministério Público pode cobrá-lo após a morte do doador omisso.", "A liberalidade pode impor dever juridicamente exigível ao donatário. A legitimidade para exigir varia conforme o beneficiário e a atuação do doador.", "Terreno é doado com obrigação de manter biblioteca comunitária; descumprido o encargo, sua execução pode ser exigida.", "Encargo não se confunde com simples conselho. A intervenção do Ministério Público exige interesse geral e as condições temporais indicadas no artigo.", "Encargo", "obrigação imposta ao beneficiário de uma liberalidade"),
    "554": row("A doação destinada a entidade que ainda será criada perde eficácia se ela não for regularmente constituída em dois anos.", "A lei admite beneficiar pessoa jurídica futura, mas condiciona a liberalidade à constituição regular dentro de prazo certo.", "Doador reserva recursos a uma fundação em formação; se ela não existir regularmente em dois anos, a doação caduca.", "Não basta atuação informal: a entidade deve estar juridicamente constituída. O prazo legal não se confunde com prazo contratual para cumprir encargo.", "Caducidade", "perda de eficácia pelo não atendimento de condição ou prazo legal"),
    "555": row("A doação pode ser desfeita por grave ingratidão do beneficiário ou por descumprimento do encargo imposto.", "A revogação não decorre de mero arrependimento. Exige uma causa legal ligada à conduta do donatário ou à obrigação assumida com a liberalidade.", "Donatário deixa de cumprir encargo de manter equipamento doado para serviço comunitário, permitindo pedido de revogação.", "As duas causas possuem requisitos e efeitos próprios nos artigos seguintes. O negócio não se desfaz automaticamente com a alegação do doador.", "Revogação", "desfazimento da doação por causa prevista em lei"),
    "556": row("O doador não pode abrir mão antecipadamente do direito de revogar a doação por ingratidão futura.", "A proteção contra atos graves do donatário é indisponível antes de o fato ocorrer. Cláusula prévia de renúncia não impede posterior reação legal.", "Contrato de doação declara que nenhuma conduta futura permitirá revogação; a cláusula não afasta as hipóteses legais de ingratidão.", "O artigo trata da renúncia antecipada. Perdão ou outras condutas posteriores ao fato exigem análise própria e não se confundem com essa vedação.", "Renúncia antecipada", "abandono de um direito antes de nascer a situação que permitiria exercê-lo"),
    "557": row("A ingratidão autoriza revogação quando o donatário atenta contra a vida do doador, pratica homicídio doloso, ofensa física, injúria grave, calúnia ou recusa alimentos necessários que podia fornecer.", "O rol identifica comportamentos graves incompatíveis com a liberalidade recebida. Cada hipótese depende de prova de seus elementos, inclusive capacidade de prestar alimentos na última.", "Donatário com recursos recusa assistência alimentar indispensável ao doador necessitado, que pede a revogação.", "Desavença comum ou simples falta de gratidão não bastam. A conduta deve se enquadrar em hipótese legal e observar prazo e legitimidade.", "Ingratidão", "conduta grave do donatário que permite revogar a doação"),
    "558": row("A revogação por ingratidão também é possível quando a vítima da conduta grave é cônjuge, ascendente, descendente, inclusive adotivo, ou irmão do doador.", "A proteção se estende a familiares próximos. O doador pode reagir mesmo quando a agressão não foi dirigida pessoalmente contra ele.", "Donatário comete ofensa física contra o pai do doador; o vínculo familiar permite examinar a revogação.", "A extensão alcança somente as pessoas indicadas e continua dependente de uma das condutas tipificadas no artigo anterior.", "Ascendente", "parente de geração anterior, como pai, mãe, avô ou avó"),
    "559": row("O pedido de revogação por ingratidão deve ser apresentado em um ano contado da ciência, pelo doador, do fato e de sua autoria pelo donatário.", "O prazo só começa quando o doador conhece tanto o acontecimento que autoriza a medida quanto a identidade de seu autor.", "Doador descobre meses depois que o donatário praticou a agressão; o prazo anual corre dessa descoberta completa.", "A demora em conhecer a autoria pode afetar o termo inicial, mas ciência e datas precisam ser provadas. O prazo não vale indistintamente para revogação por encargo.", "Termo inicial", "momento a partir do qual um prazo começa a correr"),
    "560": row("O direito de iniciar revogação não passa aos herdeiros do doador nem atinge automaticamente os do donatário. Se a ação já começou, porém, pode prosseguir entre os respectivos sucessores.", "A iniciativa é pessoal do doador, mas o processo validamente instaurado adquire conteúdo patrimonial transmissível para continuidade.", "Doador ajuíza a ação e morre; seus herdeiros podem continuá-la contra o donatário ou seus sucessores.", "Sem ação iniciada pelo doador, os herdeiros não podem inaugurar o pedido, ressalvada a exceção específica do homicídio doloso.", "Intransmissibilidade", "impossibilidade de transferir a outra pessoa determinado direito pessoal"),
    "561": row("Se o doador for vítima de homicídio doloso praticado pelo donatário, seus herdeiros podem pedir a revogação, salvo perdão do falecido.", "A morte causada pelo próprio beneficiário justifica exceção à regra de iniciativa pessoal, permitindo que os sucessores atuem.", "Donatário mata intencionalmente o doador; não havendo perdão, os herdeiros ajuízam a revogação.", "É necessária conduta dolosa e ausência de perdão. A exceção não autoriza herdeiros a iniciar ação em qualquer outra hipótese de ingratidão.", "Homicídio doloso", "morte provocada com intenção ou aceitação consciente do resultado"),
    "562": row("A doação com encargo pode ser revogada quando o donatário, em mora, não o cumpre. Sem prazo definido, o doador pode notificá-lo judicialmente e conceder período razoável.", "Antes da revogação, deve existir atraso juridicamente caracterizado. A notificação supre a falta de vencimento ao fixar oportunidade concreta de cumprimento.", "Imóvel é doado para instalação de escola sem data marcada; o doador notifica e fixa prazo razoável antes de pedir revogação.", "Descumprimento e mora precisam ser demonstrados. A revogação não deve ser confundida com a cobrança direta do encargo.", "Doação onerosa", "doação acompanhada de obrigação imposta ao donatário"),
    "563": row("A revogação por ingratidão preserva direitos de terceiros e frutos anteriores à citação válida. O donatário deve entregar os frutos posteriores e, se não puder devolver o bem, indenizar por valor intermediário.", "A lei protege relações já constituídas e fixa consequências patrimoniais conforme o momento processual e a possibilidade de restituição material.", "Antes de citado, donatário colhe frutos regularmente; depois da citação, deve entregá-los ou responder por eles.", "O artigo disciplina ingratidão. Direitos de terceiros não são apagados pela revogação, e a indenização não corresponde automaticamente ao maior valor possível.", "Frutos", "rendimentos ou utilidades periodicamente produzidos pelo bem"),
    "564": row("Não cabe revogação por ingratidão nas doações remuneratórias, nas doações com encargo já cumprido, nas feitas para satisfazer obrigação natural ou para casamento determinado.", "A natureza ou a finalidade dessas liberalidades impede o desfazimento por ingratidão, mesmo diante de conduta posterior do donatário.", "Pessoa doa quantia como recompensa por serviço não exigível; depois não pode usar ingratidão para revogá-la.", "A exclusão é específica da ingratidão. Outros defeitos do negócio ou causas legais distintas não são automaticamente afastados.", "Obrigação natural", "dever sem cobrança judicial, mas cujo cumprimento voluntário é juridicamente reconhecido"),
    "565": row("Locação de coisa é o contrato pelo qual se cede, mediante remuneração, o uso e a fruição de bem não fungível por prazo determinado ou indeterminado.", "O locatário recebe uso temporário, não propriedade. A individualidade do bem e o aluguel distinguem a locação de mútuo e comodato.", "Empresa aluga máquina identificada por seis meses e paga valor mensal ao proprietário.", "Regras especiais podem reger certas locações. Coisa consumível substituível e empréstimo gratuito pertencem a regimes jurídicos diferentes.", "Coisa não fungível", "bem individualizado que não pode ser substituído indiferentemente por outro"),
    "566": row("O locador deve entregar a coisa e suas pertenças em condições de uso, conservá-la assim durante o contrato, salvo pacto expresso, e assegurar posse tranquila ao locatário.", "O dever não termina na entrega: abrange manutenção da aptidão contratada e proteção do uso contra interferências juridicamente relevantes.", "Proprietário entrega equipamento funcional e providencia reparo estrutural necessário para manter seu uso normal.", "Cláusula expressa pode redistribuir a manutenção dentro dos limites aplicáveis. Desgaste causado pelo locatário não é dever normal do locador.", "Uso pacífico", "utilização sem perturbação jurídica ou material imputável ao locador"),
    "567": row("Se a coisa se deteriora sem culpa do locatário, ele pode obter redução proporcional do aluguel ou encerrar o contrato quando o bem já não atende à finalidade prevista.", "A consequência varia conforme a gravidade: perda parcial de utilidade justifica abatimento; inutilidade para o fim contratado permite resolução.", "Câmara frigorífica perde parte da capacidade sem culpa do usuário; o aluguel é reduzido enquanto persiste a limitação.", "É preciso provar deterioração, ausência de culpa e impacto funcional. A resolução não decorre de defeito irrelevante.", "Deterioração", "perda parcial de qualidade, valor ou utilidade do bem"),
    "568": row("O locador deve proteger o locatário contra perturbações de terceiros fundadas em direito e responde por defeitos que já existiam quando a locação começou.", "O locatário tem garantia contra reivindicações jurídicas externas e contra vícios anteriores que prejudiquem o uso contratado.", "Terceiro reivindica judicialmente a máquina alugada com base em propriedade anterior; o locador deve resguardar o uso do locatário.", "Incômodo meramente factual sem pretensão de direito recebe tratamento distinto. Defeitos posteriores podem depender de causa e das demais obrigações contratuais.", "Turbação", "perturbação que restringe o exercício da posse ou do uso"),
    "569": row("O locatário deve usar e cuidar da coisa conforme contrato e natureza, pagar pontualmente, comunicar pretensões de terceiros e devolvê-la no fim, ressalvado o desgaste normal.", "O artigo reúne deveres de conservação, pagamento, cooperação e restituição, todos orientados pelo uso regular da coisa.", "Locatário usa veículo conforme combinado, informa tentativa de apreensão por terceiro e o devolve com desgaste comum.", "Desgaste natural não gera indenização. Dano por abuso, desvio de uso ou falta de comunicação pode produzir responsabilidade própria.", "Uso convencionado", "finalidade de utilização definida pelas partes no contrato"),
    "570": row("Uso diferente do ajustado ou dano por abuso permite ao locador resolver a locação e cobrar perdas e danos.", "A violação relevante do modo de utilização autoriza simultaneamente desfazer o vínculo e reparar prejuízos comprovados.", "Máquina leve é empregada em atividade pesada proibida e sofre dano; o locador encerra o contrato e exige indenização.", "A reparação exige dano e nexo causal. Pequena irregularidade sem gravidade não deve ser automaticamente equiparada a abuso destrutivo.", "Abuso", "uso excessivo ou incompatível com a finalidade legítima do bem"),
    "571": row("Durante prazo certo, o locador só retoma antecipadamente indenizando os prejuízos; o locatário só devolve antes pagando multa proporcional. Este pode reter o bem até receber a indenização.", "A estabilidade temporal vincula ambos. A saída antecipada tem custo, e a retenção protege o crédito indenizatório do locatário.", "Locador quer a máquina antes do fim; deve ressarcir prejuízos, e o locatário pode conservá-la até o pagamento.", "A multa devida pelo locatário deve ser proporcional. Retenção não transforma o locatário em proprietário nem autoriza uso além do necessário.", "Direito de retenção", "faculdade de conservar a coisa até receber crédito ligado a ela"),
    "572": row("Quando a cobrança dos aluguéis restantes como indenização se torna excessiva, o juiz pode reduzi-la a valor razoável.", "A norma impede que a saída antecipada gere penalidade desproporcional, permitindo adequação judicial às circunstâncias.", "Locatário devolve cedo equipamento que é imediatamente alugado a terceiro; o juiz reduz indenização equivalente a todo o período restante.", "A redução não é automática nem elimina toda responsabilidade. É preciso demonstrar excesso em relação ao prejuízo e ao contrato.", "Equidade judicial", "adequação da solução pelo juiz para evitar resultado desproporcional"),
    "573": row("A locação com prazo determinado termina automaticamente quando chega a data final, sem necessidade de aviso ou notificação.", "O vencimento previamente conhecido extingue o período contratual, salvo prorrogação decorrente de nova manifestação ou da continuidade tolerada.", "Contrato de equipamento acaba em 30 de junho; nessa data surge o dever de restituição sem aviso adicional.", "A permanência do locatário sem oposição pode gerar prorrogação por prazo indeterminado conforme o artigo seguinte.", "Pleno direito", "efeito que ocorre diretamente pela lei, sem ato adicional"),
    "574": row("Após o término, se o locatário permanece com a coisa e o locador não se opõe, presume-se renovação por prazo indeterminado e pelo mesmo aluguel.", "A tolerância do proprietário transforma a relação vencida em locação sem data final, preservando o valor remuneratório anterior.", "Locatário continua usando máquina após seis meses e o locador segue recebendo aluguel sem protestar; a locação se prorroga.", "A presunção depende de posse continuada e ausência de oposição. Não se renova necessariamente o prazo original.", "Prorrogação tácita", "continuação do contrato inferida da conduta das partes"),
    "575": row("Locatário notificado que não devolve a coisa paga aluguel fixado pelo locador e responde até por dano fortuito. Valor manifestamente excessivo pode ser reduzido judicialmente, preservado seu caráter punitivo.", "A retenção indevida agrava a responsabilidade e permite remuneração coercitiva destinada a estimular a devolução.", "Após notificação, usuário retém equipamento; paga valor arbitrado e assume risco de dano acidental enquanto persiste a mora.", "O locador não pode impor valor abusivo sem controle. A responsabilidade agravada começa com a retenção após notificação válida.", "Aluguel-pena", "valor com função remuneratória e punitiva pela retenção indevida"),
    "576": row("O comprador da coisa locada só deve respeitar a locação se houver cláusula de vigência na alienação e registro adequado. Em imóvel, a saída exige notificação com noventa dias.", "Publicidade registral e cláusula expressa tornam o contrato oponível ao adquirente. Sem elas, há proteção temporária mínima ao ocupante de imóvel.", "Imóvel alugado é vendido sem cláusula registrada; o comprador pode encerrar a locação, mas observa noventa dias após notificar.", "Móveis registram-se em Títulos e Documentos do domicílio do locador; imóveis, no registro imobiliário competente. Leis especiais podem trazer disciplina adicional.", "Cláusula de vigência", "previsão de que a locação continua mesmo se o bem for vendido"),
    "577": row("A morte do locador ou do locatário não encerra locação por prazo determinado; a posição contratual passa aos herdeiros.", "A relação temporária sobrevive à sucessão, preservando direitos e deveres até o termo ou outra causa de extinção.", "Locatário falece no meio de contrato anual de máquina; seus herdeiros assumem a posição pelo período restante.", "A regra mencionada é para prazo determinado. A natureza do bem, do uso e eventual legislação especial também deve ser considerada.", "Sucessão contratual", "passagem de direitos e deveres do contrato aos herdeiros"),
    "578": row("Salvo pacto diverso, o locatário pode reter a coisa por benfeitorias necessárias e por úteis realizadas com consentimento expresso do locador.", "A retenção garante indenização de melhorias protegidas. Obras úteis exigem autorização expressa; as necessárias recebem proteção pela própria função conservativa.", "Locatário repara estrutura indispensável e conserva o bem até ser indenizado, se não houver cláusula válida em contrário.", "Benfeitoria apenas estética não está incluída. O contrato pode dispor de forma diversa, e cada obra deve ser corretamente classificada.", "Benfeitoria necessária", "obra indispensável para conservar o bem ou evitar sua deterioração"),
    "579": row("Comodato é empréstimo gratuito de bem não fungível e se constitui quando o objeto é efetivamente entregue.", "O comodatário recebe uso temporário da mesma coisa, sem remuneração e sem aquisição da propriedade. É contrato real, dependente da tradição.", "Pessoa entrega gratuitamente sua câmera identificada a amigo, que deverá devolver aquela mesma câmera.", "Promessa sem entrega ainda não perfaz o comodato. Se houver pagamento ou restituição por equivalente, pode tratar-se de outro contrato.", "Comodato", "empréstimo gratuito para uso, com devolução da própria coisa"),
    "580": row("Tutor, curador ou administrador de patrimônio alheio só pode emprestar gratuitamente esses bens com autorização especial.", "Como o comodato não gera remuneração, a lei restringe atos que possam reduzir a utilidade do patrimônio administrado em benefício de terceiro.", "Curador deseja ceder gratuitamente veículo da pessoa curatelada; precisa de autorização específica.", "A autorização deve abranger o ato concreto. O administrador não pode tratar bem alheio como se fosse de livre disposição pessoal.", "Administrador de bens alheios", "quem gere patrimônio pertencente a outra pessoa"),
    "581": row("Sem prazo expresso, o comodato dura o período necessário ao uso concedido. O comodante só interrompe antes por necessidade urgente e imprevista reconhecida judicialmente.", "A finalidade ajustada determina a duração implícita e protege o comodatário contra retirada arbitrária durante o uso legitimamente concedido.", "Máquina foi emprestada para uma colheita; em regra, deve permanecer até concluir essa finalidade.", "A necessidade do comodante precisa ser nova, urgente e reconhecida pelo juiz. Encerrado o prazo ou o uso, nasce o dever de devolver.", "Prazo presumido", "duração inferida da finalidade para a qual a coisa foi entregue"),
    "582": row("O comodatário deve conservar e usar a coisa conforme contrato ou natureza. Se atrasar a devolução, responde pela mora e paga aluguel arbitrado pelo comodante até restituí-la.", "A gratuidade não elimina deveres rigorosos de cuidado e restituição. Desvio de uso e retenção tardia geram perdas e encargos.", "Amigo usa câmera emprestada em ambiente proibido e depois não a devolve no prazo; responde pelos danos e aluguel.", "O aluguel decorrente da mora é sanção pela retenção, não transforma retroativamente o comodato em locação.", "Comodatário", "pessoa que recebe gratuitamente a coisa para usar e devolver"),
    "583": row("Se bens do comodatário e a coisa emprestada correm o mesmo risco, ele responde pelo dano quando salva os próprios e abandona o bem do comodante, mesmo em evento fortuito.", "O dever de lealdade impede priorizar patrimônio próprio diante de perigo comum e agrava a responsabilidade por escolha discriminatória.", "Durante inundação, comodatário salva seus equipamentos equivalentes e deixa perecer apenas o objeto emprestado.", "É necessário perigo simultâneo e possibilidade relevante de escolha. Caso fortuito não exonera quando o dano decorre dessa preferência indevida.", "Caso fortuito", "evento inevitável ou imprevisível normalmente capaz de afastar responsabilidade"),
    "584": row("Despesas ligadas ao uso e à fruição da coisa emprestada não podem ser cobradas do comodante.", "Quem recebe gratuitamente o benefício assume os custos ordinários de utilizá-lo, sem converter o comodato em fonte de reembolso.", "Comodatário abastece e faz limpeza rotineira do veículo emprestado; não pode exigir essas despesas do proprietário.", "A regra alcança gastos de uso. Despesa extraordinária e indispensável para conservar a coisa pode exigir análise distinta conforme o caso.", "Despesa de uso", "custo ordinário necessário para aproveitar a coisa emprestada"),
    "585": row("Quando várias pessoas recebem simultaneamente a mesma coisa em comodato, todas respondem solidariamente perante o comodante.", "O proprietário pode exigir de qualquer comodatário a reparação integral de obrigação decorrente do empréstimo comum, com acerto interno posterior.", "Três pessoas recebem equipamento emprestado e o danificam; o comodante pode cobrar a indenização inteira de uma delas.", "Solidariedade não significa culpa automática por qualquer fato, mas amplia a garantia externa nas responsabilidades do comodato conjunto.", "Responsabilidade solidária", "possibilidade de cobrar de qualquer obrigado a totalidade da prestação"),
    "586": row("Mútuo é empréstimo de bem fungível; o mutuário devolve outro da mesma espécie, qualidade e quantidade, e não a unidade originalmente recebida.", "O bem é destinado ao consumo ou disposição do mutuário. A restituição por equivalente distingue o mútuo do comodato.", "Pessoa recebe cem sacas de grão e depois devolve cem sacas equivalentes do mesmo padrão.", "Dinheiro é exemplo de bem fungível. Se deve ser devolvida a própria coisa individualizada, o regime adequado é o comodato.", "Mútuo", "empréstimo com transferência do bem e devolução de equivalente"),
    "587": row("A entrega no mútuo transfere a propriedade ao mutuário, que passa a suportar os riscos da coisa.", "Como o mutuário pode consumir ou alienar o recebido, eventual perda das unidades não elimina o dever de restituir equivalente.", "Dinheiro emprestado é furtado após a entrega; o mutuário continua obrigado a devolver a quantia correspondente.", "A transferência ocorre com a tradição. O risco não se confunde com juros ou prazo, que dependem de outras regras e do contrato.", "Domínio", "propriedade jurídica do bem, com poderes de usar e dispor"),
    "588": row("Empréstimo feito a menor sem autorização prévia de seu responsável não pode, em regra, ser cobrado do menor nem de seus fiadores.", "A norma desestimula crédito concedido sem controle de quem exerce a guarda e estende a proteção às garantias acessórias.", "Credor entrega dinheiro diretamente a adolescente sem consentimento do responsável e depois tenta cobrar do fiador.", "A proteção admite as exceções do artigo seguinte. Também é necessário verificar capacidade e autorização no momento da contratação.", "Fiador", "pessoa que garante dívida alheia perante o credor"),
    "589": row("O mútuo ao menor pode ser cobrado quando houver ratificação, necessidade de alimentos na ausência do responsável, bens do trabalho, benefício do menor ou obtenção maliciosa do empréstimo.", "As exceções evitam enriquecimento injustificado e protegem crédito necessário ou validado, com limite patrimonial específico para bens ganhos pelo trabalho.", "Menor usa o valor integralmente em tratamento necessário; o benefício recebido permite afastar a regra geral de incobrável.", "Cada exceção exige prova. Na hipótese dos ganhos próprios, a execução não pode superar a capacidade desses bens.", "Ratificação", "confirmação posterior de ato inicialmente praticado sem autorização suficiente"),
    "590": row("Antes do vencimento, o mutuante pode exigir garantia se houver mudança econômica notória do mutuário que ameace a restituição.", "A deterioração evidente da solvência permite reforçar preventivamente a segurança do crédito, sem antecipar automaticamente a dívida.", "Mutuário perde patrimônio relevante antes do prazo; o credor exige garantia adequada para a futura devolução.", "A mudança deve ser perceptível e relevante. A medida é exigir garantia, não presumir por si só inadimplemento definitivo.", "Garantia", "mecanismo que aumenta a segurança de recebimento do crédito"),
    "591": row("No mútuo voltado a finalidade econômica, presume-se a cobrança de juros. Se as partes não fixarem a taxa, aplica-se a taxa legal definida pelo art. 406.", "A redação vigente desde a Lei 14.905/2024 mantém a onerosidade presumida e fornece critério subsidiário para quantificar juros não pactuados.", "Empresa recebe capital para atividade comercial sem taxa escrita; incidem juros calculados pela taxa legal.", "A presunção depende de finalidade econômica. Taxa contratada e regras especiais devem ser examinadas antes do critério legal subsidiário.", "Taxa legal", "taxa de juros determinada pela legislação quando não há percentual contratual aplicável"),
    "592": row("Sem prazo expresso, o mútuo vence na próxima colheita para produtos agrícolas, em pelo menos trinta dias para dinheiro e no período declarado pelo mutuante para outros fungíveis.", "A lei fornece prazos supletivos conforme o objeto emprestado quando as partes permanecem em silêncio.", "Empréstimo em dinheiro sem vencimento não pode ser exigido antes do mínimo de trinta dias.", "As regras cedem a prazo expressamente convencionado. Para outros bens fungíveis, a declaração do mutuante deve respeitar boa-fé e permitir cumprimento.", "Prazo supletivo", "prazo fornecido pela lei quando o contrato não estabelece outro"),
    "593": row("As normas civis deste capítulo regem prestação de serviço apenas quando a relação não estiver submetida à legislação trabalhista ou a lei especial.", "O Código Civil atua de forma residual. Antes de aplicá-lo, deve-se identificar se há vínculo de emprego ou disciplina profissional própria.", "Consultoria autônoma sem subordinação é examinada pelas regras civis, se nenhuma lei especial prevalecer.", "O nome dado ao contrato não afasta regime trabalhista quando seus requisitos existem. A qualificação depende da realidade da relação.", "Regência subsidiária", "aplicação de regras gerais somente quando não existe disciplina específica prevalente"),
    "594": row("Qualquer trabalho lícito, material ou intelectual, pode ser objeto de prestação de serviço remunerada.", "A liberdade contratual alcança atividades variadas, desde que permitidas pelo direito e acompanhadas de retribuição.", "Profissional é contratado para elaborar pesquisa e recebe honorários pelo resultado de sua atividade intelectual.", "Atividade ilícita não se torna válida por contrato. Habilitação legal e regimes especiais continuam exigíveis quando aplicáveis.", "Serviço imaterial", "atividade intelectual ou técnica que não produz necessariamente objeto físico"),
    "595": row("Se uma parte não sabe ler nem escrever, o contrato de serviço pode ser assinado por outra pessoa a seu pedido e também por duas testemunhas.", "A assinatura a rogo permite formalizar a vontade de pessoa não alfabetizada, com testemunhas que reforçam a autenticidade do ato.", "Contratante não alfabetizado pede que terceiro assine por ele, e duas testemunhas subscrevem o instrumento.", "A assinatura deve corresponder à vontade real da parte. A forma especial não legitima fraude, coação ou conteúdo não compreendido.", "Assinatura a rogo", "assinatura feita por terceiro a pedido de quem não pode assinar"),
    "596": row("Quando não existe valor estipulado nem acordo posterior, a remuneração é arbitrada considerando costume local, duração e qualidade do serviço.", "A ausência de preço não torna automaticamente gratuito o trabalho; critérios objetivos permitem estabelecer contraprestação razoável.", "Técnico executa serviço sem orçamento fechado; o valor é fixado conforme padrão local, tempo e complexidade.", "Arbitramento depende de prova dos critérios e não autoriza valor desconectado do serviço efetivamente prestado.", "Arbitramento", "fixação do valor por avaliação baseada em critérios jurídicos e econômicos"),
    "597": row("A remuneração é paga depois do serviço, salvo se contrato ou costume determinar adiantamento ou parcelas.", "A regra supletiva vincula pagamento à execução, mas permite que as partes ou práticas do setor organizem fluxo diferente.", "Consultor recebe ao concluir o relatório; em setor que trabalha com sinal, parte pode ser antecipada.", "O artigo trata do momento do pagamento, não dispensa prova da prestação nem afasta condições expressamente ajustadas.", "Retribuição", "pagamento devido como contraprestação pelo serviço"),
    "598": row("Contrato de serviço não pode durar mais de quatro anos, mesmo ligado a dívida ou obra determinada; alcançado esse limite, termina ainda que a obra continue incompleta.", "A limitação protege a liberdade do prestador e impede vínculo civil excessivamente longo por um único ajuste.", "Profissional é contratado por seis anos para quitar dívida; ao completar quatro anos, o contrato se encerra.", "Nada impede novo vínculo juridicamente válido após o término, mas não se pode usar a renovação para fraudar o limite e regimes protetivos.", "Prazo máximo", "limite temporal que o contrato não pode ultrapassar"),
    "599": row("Sem prazo definido ou inferível, qualquer parte pode encerrar o contrato mediante aviso: oito dias para pagamento mensal ou maior, quatro para semanal ou quinzenal e véspera para período inferior a sete dias.", "O aviso prévio equilibra a liberdade de terminar relação indeterminada com tempo mínimo para adaptação da outra parte.", "Prestador remunerado por mês comunica a saída com oito dias de antecedência.", "Os prazos dependem da periodicidade remuneratória. Prazo contratual, natureza do serviço ou costume podem afastar a hipótese de duração indeterminada.", "Aviso prévio", "comunicação antecipada de que a relação será encerrada"),
    "600": row("Período em que o prestador deixa de trabalhar por culpa própria não integra a contagem do prazo contratual.", "A ausência imputável ao prestador suspende o avanço do tempo devido, evitando que ele se beneficie do próprio descumprimento.", "Contrato prevê cem dias; prestador falta culposamente por cinco, que não são contados como serviço cumprido.", "A exclusão exige culpa do prestador. Interrupção causada pelo contratante ou força maior demanda análise diferente.", "Tempo útil contratual", "período efetivamente computável para cumprir a duração ajustada"),
    "601": row("Sem contratação para tarefa específica, o prestador assume serviços compatíveis com suas forças e condições pessoais.", "A obrigação genérica não é ilimitada: abrange atividades razoavelmente adequadas à capacidade física, técnica e profissional do contratado.", "Auxiliar contratado genericamente pode executar tarefas compatíveis com sua qualificação, mas não atividade técnica para a qual não está habilitado.", "O contratante não pode exigir trabalho ilícito, perigoso ou incompatível. As condições concretas delimitam o conteúdo da obrigação.", "Compatibilidade funcional", "adequação da tarefa à capacidade e às condições do prestador"),
    "602": row("Prestador contratado por prazo certo ou obra determinada não pode abandonar o serviço sem justa causa. Se o fizer, recebe o vencido, mas indeniza danos; igual consequência ocorre na dispensa por justa causa.", "A remuneração já adquirida é preservada, enquanto a ruptura culposa gera responsabilidade pelos prejuízos causados.", "Profissional abandona obra sem motivo após metade do trabalho; recebe a parte vencida e indeniza custo adicional comprovado.", "Perdas e danos não são automáticas em valor fixo: exigem nexo e prova. Justa causa deve ser demonstrada.", "Justa causa", "motivo grave que autoriza legitimamente o encerramento antecipado"),
    "603": row("Se o prestador é dispensado sem justa causa, recebe integralmente a remuneração vencida e metade do que ganharia até o fim do prazo contratual.", "A fórmula legal compensa a ruptura imotivada sem assegurar todo o valor futuro, equilibrando pagamento já devido e expectativa frustrada.", "Contrato ainda teria quatro parcelas; além das vencidas, o prestador recebe metade das parcelas restantes.", "A regra pressupõe contrato sujeito a este capítulo e dispensa sem justa causa. Não deve ser transportada automaticamente para relação de emprego.", "Retribuição vincenda", "remuneração que venceria futuramente se o contrato continuasse"),
    "604": row("Encerrado o vínculo, o prestador pode exigir declaração formal de término; o mesmo vale quando foi dispensado injustamente ou saiu por motivo justo.", "O documento comprova o fim da relação e as circunstâncias juridicamente relevantes para o histórico profissional e eventual controvérsia.", "Após concluir serviço anual, profissional pede declaração escrita de que o contrato terminou regularmente.", "A declaração não substitui quitação de valores nem impede discussão sobre danos. Seu conteúdo deve corresponder ao motivo real do encerramento.", "Declaração de término", "documento que confirma o encerramento da relação de serviço"),
    "605": row("O contratante não pode transferir a terceiro o direito ao serviço, nem o prestador indicar substituto, sem concordância da outra parte.", "A confiança nas pessoas envolvidas limita a cessão de posições e a substituição unilateral, preservando características consideradas na contratação.", "Designer contratado pessoalmente não pode mandar outro profissional executar o projeto sem consentimento do cliente.", "A anuência pode permitir alteração. O artigo não impede organização interna autorizada quando o contrato não é personalíssimo e a outra parte concorda.", "Caráter pessoal", "relevância da identidade da parte para a contratação e execução"),
    "606": row("Prestador sem habilitação ou requisito legal não cobra remuneração normal. Se agiu de boa-fé e gerou benefício, pode receber compensação razoável, salvo proibição de ordem pública.", "A lei evita validar exercício irregular, mas também impede vantagem injustificada do beneficiário quando a falta não envolve proibição protetiva absoluta.", "Pessoa sem requisito formal presta serviço útil acreditando estar regular; o juiz pode fixar compensação inferior à remuneração comum.", "Boa-fé e benefício devem ser provados. Se a atividade é proibida por norma de ordem pública, nem a compensação excepcional é cabível.", "Ordem pública", "regra obrigatória voltada a proteger interesse fundamental da coletividade"),
    "607": row("O contrato termina pela morte de qualquer parte, fim do prazo, conclusão da obra, aviso prévio, inadimplemento ou impossibilidade de continuidade por força maior.", "A enumeração reúne causas pessoais, temporais, funcionais e supervenientes que encerram a prestação civil de serviço.", "Prestação personalíssima torna-se impossível pela morte do profissional, extinguindo o vínculo.", "Cada causa produz efeitos próprios sobre remuneração e indenização. Força maior exige impossibilidade real, não simples aumento de dificuldade.", "Força maior", "evento inevitável que impede a continuidade da obrigação"),
    "608": row("Quem induz pessoa vinculada por contrato escrito a abandonar serviço deve indenizar o contratante pelo equivalente a dois anos da remuneração ajustada.", "A regra responsabiliza o terceiro que interfere conscientemente em vínculo formal e provoca seu rompimento.", "Concorrente alicia profissional preso a contrato escrito; paga ao contratante valor correspondente a dois anos do ajuste desfeito.", "É preciso demonstrar aliciamento, contrato escrito e nexo com a ruptura. Contratação após término regular não se enquadra automaticamente.", "Aliciamento", "indução de pessoa a romper vínculo para prestar serviço a outro"),
    "609": row("A venda do imóvel rural onde ocorre o serviço não encerra o contrato; o prestador escolhe continuar com o comprador ou com o contratante original.", "A mudança de proprietário preserva o vínculo e dá ao prestador opção sobre com quem manterá a prestação.", "Fazenda é vendida durante contrato de serviço; trabalhador civil escolhe seguir com o adquirente ou com o antigo dono.", "A norma não transfere compulsoriamente o prestador. O regime é civil e não substitui regras trabalhistas quando houver relação de emprego.", "Alienação", "transferência da propriedade do bem a outra pessoa"),
    "610": row("Na empreitada, o empreiteiro pode fornecer apenas trabalho ou também materiais. O fornecimento de materiais exige lei ou acordo; projeto não inclui automaticamente execução nem fiscalização.", "O artigo separa empreitada de mão de obra e mista, além de delimitar obrigações do autor de projeto para evitar extensão presumida do contrato.", "Arquiteto é contratado somente para projetar; não deve construir ou fiscalizar sem ajuste adicional.", "Materiais não se presumem incluídos. É essencial identificar o escopo, pois prestação de serviços e empreitada possuem riscos e resultados distintos.", "Empreitada", "contrato voltado à realização de obra ou resultado determinado"),
}
